// Preparation instrument. No production result exists until the frozen run,
// complete journals and a separate verifier are admitted.
#include <pari/pari.h>
#include <gmpxx.h>
#include <openssl/sha.h>
#include <algorithm>
#include <array>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
using Z=mpz_class;
using Seed=std::array<unsigned char,20>;
static void require(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
static Z integer(const std::string& s){Z z;require(z.set_str(s,0)==0,"integer input");return z;}
static std::string hexbytes(const unsigned char* p,size_t n){std::ostringstream s;s<<std::hex<<std::setfill('0');for(size_t i=0;i<n;++i)s<<std::setw(2)<<unsigned(p[i]);return s.str();}
static std::vector<unsigned char> unhex(const std::string& s,size_t n){require(s.size()==2*n,"hex width");std::vector<unsigned char> b;for(size_t i=0;i<s.size();i+=2){require(s.find_first_not_of("0123456789abcdefABCDEF",i)>=i+2,"hex digit");b.push_back(static_cast<unsigned char>(std::stoul(s.substr(i,2),nullptr,16)));}return b;}
static Z frombytes(const unsigned char* p,size_t n){Z z;mpz_import(z.get_mpz_t(),n,1,1,1,0,p);return z;}
static Z mod(const Z& a,const Z& p){Z z;mpz_mod(z.get_mpz_t(),a.get_mpz_t(),p.get_mpz_t());return z;}
static Z power(const Z& a,const Z& e,const Z& p){Z z;mpz_powm(z.get_mpz_t(),a.get_mpz_t(),e.get_mpz_t(),p.get_mpz_t());return z;}
static Z inv(const Z& a,const Z& p){Z z;require(mpz_invert(z.get_mpz_t(),a.get_mpz_t(),p.get_mpz_t())!=0,"nonunit inverse");return z;}
static GEN pari_z(const Z& z){return gp_read_str(z.get_str().c_str());}
static Z native_z(GEN n){char* s=GENtostr(n);Z z(s,10);pari_free(s);return z;}
static std::vector<std::string> fields(const std::string& line){std::istringstream in(line);std::vector<std::string> r;std::string x;while(std::getline(in,x,'\t'))r.push_back(x);return r;}
struct Model{std::string id;int bits;Z p,b,n;Seed seed;};
static std::vector<Model> models(const fs::path& path){std::ifstream f(path);require(bool(f),"cohort input");std::vector<Model> r;std::string line;while(std::getline(f,line)){if(line.empty()||line[0]=='#')continue;auto c=fields(line);require(c.size()==9,"cohort columns");Model m;m.id=c[0];m.bits=std::stoi(c[1]);m.p=integer(c[5]);m.b=integer(c[6]);m.n=integer(c[7]);auto bytes=unhex(c[8].substr(2),20);std::copy(bytes.begin(),bytes.end(),m.seed.begin());r.push_back(m);}require(r.size()==21,"all21 source models");return r;}
static Z expand(const Seed& seed,int bits){int v=(bits-1)/160,w=bits-160*v-1;unsigned char hash[SHA_DIGEST_LENGTH];SHA1(seed.data(),seed.size(),hash);Z c=frombytes(hash,sizeof(hash));mpz_fdiv_r_2exp(c.get_mpz_t(),c.get_mpz_t(),static_cast<mp_bitcnt_t>(w));Z z=frombytes(seed.data(),seed.size());for(int i=1;i<=v;++i){Z zi=z+i;mpz_fdiv_r_2exp(zi.get_mpz_t(),zi.get_mpz_t(),160);Seed si{};size_t used=0;unsigned char tmp[20]{};mpz_export(tmp,&used,1,1,1,0,zi.get_mpz_t());std::copy(tmp,tmp+used,si.begin()+static_cast<std::ptrdiff_t>(20-used));SHA1(si.data(),si.size(),hash);c=(c<<160)+frombytes(hash,sizeof(hash));}return c;}
static Seed draw(const std::vector<unsigned char>& nonce,int bits,uint64_t index){const std::string domain="ICV1-random-curve-calibration/v1";std::vector<unsigned char> msg(domain.begin(),domain.end());msg.push_back(0);msg.insert(msg.end(),nonce.begin(),nonce.end());msg.push_back(static_cast<unsigned char>(bits>>8));msg.push_back(static_cast<unsigned char>(bits));for(int j=7;j>=0;--j)msg.push_back(static_cast<unsigned char>(index>>(8*j)));unsigned char digest[SHA256_DIGEST_LENGTH];SHA256(msg.data(),msg.size(),digest);Seed s{};std::copy(digest,digest+20,s.begin());return s;}
static Z sqrt_small(const Z& a,const Z& p){require(mpz_legendre(a.get_mpz_t(),p.get_mpz_t())>=0,"nonresidue square root");if(a==0)return 0;Z y;if(mpz_fdiv_ui(p.get_mpz_t(),4)==3)y=power(a,(p+1)/4,p);else{pari_sp saved=avma;GEN r=Fp_sqrt(pari_z(a),pari_z(p));require(r!=nullptr,"PARI square root");y=native_z(r);avma=saved;}Z other=p-y;return std::min(y,other);}
static bool coefficient(const Z& p,int bits,const Seed& seed,Z& c,Z& b,std::string& why){c=expand(seed,bits);Z cm=mod(c,p);if(cm==0){why="zero_c";return false;}if(mod(4*cm+27,p)==0){why="singular";return false;}Z rhs=mod(-27*inv(cm,p),p);if(mpz_legendre(rhs.get_mpz_t(),p.get_mpz_t())<0){why="nonsquare_b";return false;}if(mpz_fdiv_ui(p.get_mpz_t(),4)==3)b=power(rhs,(p+1)/4,p);else b=sqrt_small(rhs,p);require(mod(cm*b*b+27,p)==0,"seed equation");return true;}
struct Point{Z x=0,y=0;bool inf=true;};
static Point add(const Point& u,const Point& v,const Z& p){if(u.inf)return v;if(v.inf)return u;if(u.x==v.x&&mod(u.y+v.y,p)==0)return Point{};Z slope;if(u.x==v.x)slope=mod((3*u.x*u.x-3)*inv(mod(2*u.y,p),p),p);else slope=mod((v.y-u.y)*inv(mod(v.x-u.x,p),p),p);Point w;w.inf=false;w.x=mod(slope*slope-u.x-v.x,p);w.y=mod(slope*(u.x-w.x)-u.y,p);return w;}
static Point multiply(Point p0,Z k,const Z& p){Point out;while(k>0){if(mpz_odd_p(k.get_mpz_t()))out=add(out,p0,p);k>>=1;if(k>0)p0=add(p0,p0,p);}return out;}
static Point witness(const Z& p,const Z& b){for(Z x=0;x<10000;++x){Z rhs=mod(x*x*x-3*x+b,p);if(mpz_legendre(rhs.get_mpz_t(),p.get_mpz_t())>=0)return Point{x,sqrt_small(rhs,p),false};}throw std::runtime_error("witness search bound; operational failure, not curve rejection");}
static void certify_point(const Z& p,const Z& b,const Z& n,const Point& q){Z t=p+1-n;require(n>0&&t*t<=4*p&&n*n>16*p,"order uniqueness in Hasse interval");require(!q.inf&&q.x>=0&&q.x<p&&q.y>=0&&q.y<p,"nonzero canonical point");require(mod(q.y*q.y-q.x*q.x*q.x+3*q.x-b,p)==0,"point on curve");require(multiply(q,n,p).inf,"prime-order witness multiplication");}
static bool small_prime(int n){if(n<2)return false;for(int d=2;d<=n/d;++d)if(n%d==0)return false;return true;}
static std::pair<int,int> profile(const Z& p,const Z& n){Z t=p+1-n,d=t*t-4*p;int strict=0,zero=0;for(int ell=3;ell<=691;ell+=2)if(small_prime(ell)){Z l=ell;int ch=mpz_legendre(d.get_mpz_t(),l.get_mpz_t());strict+=ch==1;zero+=ch==0;}return {strict,zero};}
static void self_test(const fs::path& input){auto ms=models(input);for(const auto& m:ms){Z c,b;std::string why;require(coefficient(m.p,m.bits,m.seed,c,b,why),"published/skipped seed fixture "+m.id);require(mod(b*b-m.b*m.b,m.p)==0,"reference b squared "+m.id);if(mpz_fdiv_ui(m.p.get_mpz_t(),4)==3)require(b==m.b,"reference exponentiation root "+m.id);auto q=witness(m.p,b);certify_point(m.p,b,m.n,q);Point bad=q;bad.y=mod(bad.y+1,m.p);require(mod(bad.y*bad.y-bad.x*bad.x*bad.x+3*bad.x-b,m.p)!=0,"changed-point refusal fixture");}
 int tested=0;for(int p:{101,103,107})for(int b=1;b<=8;++b){if((27*b*b-108)%p==0)continue;long count=1;for(int x=0;x<p;++x)for(int y=0;y<p;++y)if((y*y-x*x*x+3*x-b)%p==0)++count;pari_sp saved=avma;GEN E=ellinit(mkvec2(stoi(-3),stoi(b)),stoi(p),DEFAULTPREC);require(equaliu(ellcard(E,nullptr),static_cast<ulong>(count)),"toy exhaustive point count");require(bool(isprime(stoi(count)))==small_prime(static_cast<int>(count)),"toy proved primality");avma=saved;++tested;}require(tested==21,"exact nonsingular toy case count");
 std::vector<unsigned char> nonce(32);require(draw(nonce,192,0)==draw(nonce,192,0),"A/A seed determinism");require(draw(nonce,192,0)!=draw(nonce,192,1)&&draw(nonce,192,0)!=draw(nonce,224,0),"seed counter/field separation");std::cout<<"PASS:21 frozen seed/root/order-point fixtures,"<<tested<<" toy point counts/primality checks,changed-point controls and deterministic seed encoding\n";}
int main(int argc,char** argv){try{pari_init(256000000,1000000);if(argc==3&&std::string(argv[1])=="--self-test"){self_test(argv[2]);return 0;}require(argc==7,"sampler --generate|--pilot COHORT BITS NONCE_HEX FRESH_DIR ACK_FROZEN_CHECKPOINT");std::string mode=argv[1];require(mode=="--generate"||mode=="--pilot","mode");require(std::string(argv[6])=="ACK_FROZEN_CHECKPOINT","explicit launch acknowledgement");auto ms=models(argv[2]);int bits=std::stoi(argv[3]);Z p=0;for(const auto& m:ms)if(m.bits==bits){if(p==0)p=m.p;require(p==m.p,"unique field modulus");}require(p>0,"one of six fixed fields");auto nonce=unhex(argv[4],32);fs::path out=argv[5];require(!fs::exists(out),"fresh output required; no implicit resume or overwrite");fs::create_directories(out);std::ofstream attempts(out/"attempts.tsv"),accepted(out/"accepted.tsv");require(bool(attempts)&&bool(accepted),"journal creation");attempts<<"bits\tindex\tseed\tc\tb\tn\tstatus\n";accepted<<"bits\tordinal\tindex\tseed\tc\tb\tn\tGx\tGy\tstrict691\tramified691\n";const uint64_t target=mode=="--pilot"?10:10000;uint64_t done=0,index=0;for(;done<target&&index<50000000;++index){pari_sp saved=avma;Seed seed=draw(nonce,bits,index);Z c,b,n;std::string disposition;bool ok=coefficient(p,bits,seed,c,b,disposition);Point q;std::pair<int,int> counts{0,0};if(ok){GEN E=ellinit(mkvec2(stoi(-3),pari_z(b)),pari_z(p),DEFAULTPREC);GEN N=ellsea(E,1);if(signe(N)==0){ok=false;disposition="composite_early_abort";}else{n=native_z(N);if(!isprime(N)){ok=false;disposition="composite_proved";}else if(n==p){ok=false;disposition="anomalous";}else if(mpz_sizeinbase(n.get_mpz_t(),2)>static_cast<size_t>(bits)){ok=false;disposition="order_width";}else{Z pk=1;for(int k=1;k<=1023;++k){pk=mod(pk*p,n);if(pk==1){ok=false;disposition="embedding_bound";break;}}if(ok){q=witness(p,b);certify_point(p,b,n,q);counts=profile(p,n);disposition="accepted";}}}}
 attempts<<bits<<'\t'<<index<<'\t'<<hexbytes(seed.data(),seed.size())<<'\t'<<c<<'\t'<<(b==0?"NA":b.get_str())<<'\t'<<(n==0?"NA":n.get_str())<<'\t'<<disposition<<'\n';attempts.flush();require(bool(attempts),"attempt journal write");if(ok){++done;accepted<<bits<<'\t'<<done<<'\t'<<index<<'\t'<<hexbytes(seed.data(),seed.size())<<'\t'<<c<<'\t'<<b<<'\t'<<n<<'\t'<<q.x<<'\t'<<q.y<<'\t'<<counts.first<<'\t'<<counts.second<<'\n';accepted.flush();require(bool(accepted),"accept journal write");}avma=saved;}
 require(done==target,"accepted target incomplete at attempt cap");std::ofstream summary(out/"completion.json");summary<<"{\"kind\":\"native-random-curve-sampling/v1\",\"mode\":\""<<mode<<"\",\"bits\":"<<bits<<",\"accepted\":"<<done<<",\"attempts\":"<<index<<",\"nonce\":\""<<argv[4]<<"\",\"separate_verification_pending\":true,\"timing_admitted\":false}\n";require(bool(summary),"completion write");std::cout<<"Completed "<<done<<" accepted curves; independent verification pending\n";pari_close();return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\nOperational failures are not curve rejections. Preserve this attempt.\n";return 1;}}
